<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/cepfms_operational_helpers.php';
requireCefPermission('cepfms.analytics.view');
$pdo=db();$summary=cefAnalyticsSummary($pdo);
$categories=$pdo->query("SELECT COALESCE(c.name,'Unclassified') category,COUNT(*) total FROM cef_submissions s LEFT JOIN cef_categories c ON c.id=s.category_id WHERE s.deleted_at IS NULL GROUP BY COALESCE(c.name,'Unclassified') ORDER BY total DESC")->fetchAll();
?>
<!doctype html><html><head><meta charset="utf-8"><title>CEPFMS Analytics Report</title><style>body{font:11px Arial;margin:25px;color:#111827}.head{text-align:center;border-bottom:3px solid #0f2137;padding-bottom:12px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:14px 0}.card{border:1px solid #ccc;border-top:4px solid #d4a90b;padding:8px}.card strong{display:block;font-size:18px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccc;padding:6px}th{background:#eee}</style></head><body onload="window.print()"><div class="head"><strong><?= e(APP_NAME) ?></strong><h2>Citizen Engagement Analytics Summary</h2><div><?= date('F j, Y g:i A') ?></div></div><div class="cards"><div class="card"><strong><?= $summary['total'] ?></strong>Total Submissions</div><div class="card"><strong><?= $summary['pending_moderation'] ?></strong>Pending Moderation</div><div class="card"><strong><?= $summary['overdue_complaints'] ?></strong>Overdue Complaints</div><div class="card"><strong><?= $summary['delivered_responses'] ?></strong>Delivered Responses</div></div><h3>Category Distribution</h3><table><thead><tr><th>Category</th><th>Total</th></tr></thead><tbody><?php foreach($categories as $r): ?><tr><td><?= e($r['category']) ?></td><td><?= (int)$r['total'] ?></td></tr><?php endforeach; ?></tbody></table></body></html>
